CREATE OR REPLACE SECURE VIEW DP_GRID.OUT_LINE_LOADING
  WITH TAG (GOV.DATA_CLASSIFICATION = 'Internal - Restricted', GOV.DATA_OWNER = 'Energy Data Engineering Team', GOV.DOMAIN = 'Energy_Operations_Package')
  COMMENT = 'Atomic contracted output for TransmissionLine'
AS
SELECT f.LINE_LOADING_ID, f.TRANSMISSION_LINE_ID, f.DATE_KEY, f.LOCATION_ID, f.CURRENT_LOAD_MW, d1.CONSTRAINT_FLAG, d1.LINE_NAME, d1.VOLTAGE_KV, d1.THERMAL_LIMIT_MW, d2.FISCAL_YEAR, d2.FULL_DATE, d2.IS_HOLIDAY, d2.IS_WEEKEND, d2.MONTH_NAME, d2.MONTH_NUMBER, d2.QUARTER, d3.CITY, d3.CLIMATE_ZONE, d3.REGION
FROM CORE.FCT_LINE_LOADING f
LEFT JOIN CORE.DIM_TRANSMISSION_LINE d1 ON f.TRANSMISSION_LINE_ID = d1.TRANSMISSION_LINE_ID
LEFT JOIN CORE.DIM_DATE d2 ON f.DATE_KEY = d2.DATE_KEY
LEFT JOIN CORE.DIM_LOCATION d3 ON f.LOCATION_ID = d3.LOCATION_ID;
